from itertools import combinations, product

edges = list(combinations(range(1,8), 2))
idx = {e:i for i,e in enumerate(edges)}

fixed = {3:0, 7:0, 12:0, 18:0}

for assign in product([0,1], repeat=21):
    ok = all(assign[k]==v for k,v in fixed.items())
    if not ok: continue
    # no red K4
    bad = False
    for quad in combinations(range(1,8),4):
        if all(assign[idx[(a,b)]]==0 for a,b in combinations(quad,2)):
            bad=True; break
    if bad: continue
    for tri in combinations(range(1,8),3):
        if all(assign[idx[(a,b)]]==1 for a,b in combinations(tri,2)):
            bad=True; break
    if bad: continue
    print(list(assign))
    break
